Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const long long MOD_A = 998244353;
const long long MOD_B = 1000000007;

long long get_input_value() {
    long long val = 0;
    int sign_flag = 1;
    char c = getchar();
    while (c < '0' || c > '9') {
        if (c == '-') sign_flag = -1;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        val = (val << 1) + (val << 3) + (c - '0');
        c = getchar();
    }
    return val * sign_flag;
}

long long total_n;
vector<int> buckets_arr[10];
long long prefix_sum_arr[10];
long long total_cnt1 = 0, total_cnt2 = 0, total_ans = 0;
int power_array[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

void generate_combinations(int length, long long value) {
    if (length > 6) return;
    buckets_arr[length].push_back((total_cnt1 - value + MOD_A) % MOD_A);
    prefix_sum_arr[length] += (total_cnt1 - value + MOD_A) % MOD_A;
    ++total_cnt1;
    for (int digit = 0; digit <= 9; ++digit) {
        generate_combinations(length + 1, value * 10 + digit);
    }
}

bool check_range(long long x) {
    return x * 1000000 + 999999 <= total_n && x * 10000000 > total_n;
}

void explore(int length, long long value) {
    if (value > total_n) return;
    if (check_range(value)) {
        for (int i = 0; i <= 6; ++i) {
            long long v1 = ((total_cnt2 + 1 - value * power_array[i]) % MOD_A + MOD_A) % MOD_A;
            int idx = lower_bound(buckets_arr[i].begin(), buckets_arr[i].end(), (int)(MOD_A - v1)) - buckets_arr[i].begin();
            total_ans = (total_ans + (prefix_sum_arr[i] + buckets_arr[i].size() * v1 - 1LL * MOD_A * (buckets_arr[i].size() - idx))) % MOD_B;
        }
        total_cnt2 += total_cnt1;
    } else {
        if (length) ++total_cnt2;
        total_ans = (total_ans + ((total_cnt2 - value) % MOD_A + MOD_A) % MOD_A) % MOD_B;
        for (int digit = (!length); digit <= 9; ++digit) {
            explore(length + 1, value * 10 + digit);
        }
    }
}

int main() {
    total_n = get_input_value();
    generate_combinations(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(buckets_arr[i].begin(), buckets_arr[i].end());
    }
    explore(0, 0);
    cout << total_ans << "\n";
    return 0;
}
